window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-080fc552e938ca95"]={"versions": [{"id": "FIG-080fc552e938ca95", "releases": ["R2.1.20"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Ablauf- bzw. Zeitstrahldiagramm zur Schedule-Table-Ausführung im AUTOSAR LIN-Interface (LIN Interface / LinIf). Es visualisiert die sequentielle Abfolge von Schedule-Tabellen-Slots auf dem LIN-Bus.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>ReadById</strong>: Diagnostischer Schedule-Tabellen-Slot (Abfrage via ReadById).\n</li><li><strong>CheckSensors</strong>: Ereignis- bzw. anwendungsspezifischer Schedule-Tabellen-Slot zur Sensorabfrage.\n</li><li><strong>Normal</strong>: Standard- bzw. zyklische Schedule-Tabellen-Slots für den regulären Kommunikationsbetrieb.\n</li><li><strong>...</strong>: Indikator für fortlaufende Schedule-Tabellen-Ausführung.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Die Schedule-Tabellen werden sequentiell von links nach rechts abgearbeitet:</p>\n<ol class=\"fig-list\"><li>Ausführung der Tabelleneinträge aus <code>ReadById</code>.\n</li><li>Nach Abschluss Übergang zur Ausführung von <code>CheckSensors</code>.\n</li><li>Anschließend Fortführung mit der zyklischen Tabelle <code>Normal</code>, die wiederholt ausgeführt wird (<code>Normal</code>, gefolgt von weiteren Zyklen <code>...</code>).\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Veranschaulicht das Umschalt- und Ausführungsverhalten angeforderter Schedule-Tabellen im LinIf gemäß Tabellenkonfiguration. Bei einem Tabellenwechsel wird die aktuell aktive Schedule-Tabelle an der definierten Umschaltgrenze abgelöst und die neu angeforderte Tabelle sequentiell abgearbeitet, bevor wieder in die reguläre zyklische Betriebsart (<code>Normal</code>) gewechselt wird.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-8655b07ad72f00e3", "releases": ["R3.0.7"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Ablauf- bzw. Zeitstrahldiagramm zur Schedule-Table-Ausführung im AUTOSAR LIN-Interface (LIN Interface / LinIf). Es visualisiert die sequentielle Abfolge von Schedule-Tabellen-Slots auf dem LIN-Bus.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>ReadById</strong>: Diagnostischer Schedule-Tabellen-Slot (Abfrage via ReadById).\n</li><li><strong>CheckSensors</strong>: Ereignis- bzw. anwendungsspezifischer Schedule-Tabellen-Slot zur Sensorabfrage.\n</li><li><strong>Normal</strong>: Standard- bzw. zyklische Schedule-Tabellen-Slots für den regulären Kommunikationsbetrieb.\n</li><li><strong>...</strong>: Indikator für fortlaufende Schedule-Tabellen-Ausführung.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Die Schedule-Tabellen werden sequentiell von links nach rechts abgearbeitet:</p>\n<ol class=\"fig-list\"><li>Ausführung der Tabelleneinträge aus <code>ReadById</code>.\n</li><li>Nach Abschluss Übergang zur Ausführung von <code>CheckSensors</code>.\n</li><li>Anschließend Fortführung mit der zyklischen Tabelle <code>Normal</code>, die wiederholt ausgeführt wird (<code>Normal</code>, gefolgt von weiteren Zyklen <code>...</code>).\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Veranschaulicht das Umschalt- und Ausführungsverhalten angeforderter Schedule-Tabellen im LinIf gemäß Tabellenkonfiguration. Bei einem Tabellenwechsel wird die aktuell aktive Schedule-Tabelle an der definierten Umschaltgrenze abgelöst und die neu angeforderte Tabelle sequentiell abgearbeitet, bevor wieder in die reguläre zyklische Betriebsart (<code>Normal</code>) gewechselt wird.</p>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-080fc552e938ca95", "to": "FIG-8655b07ad72f00e3", "fr": "R2.1.20", "tr": "R3.0.7", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
